<script setup>
import {useForm,Head,usePage} from '@inertiajs/vue3';import Settings from '../Components/Settings.vue';import Errors from '../Components/Errors.vue';import {art,modes} from '../art';
const props=defineProps({catalog:Object,freshSubjects:Array});const initial=new URL(usePage().url,'http://local').searchParams.get('mode');
const form=useForm({mode:['fresh','tutor','exam'].includes(initial)?initial:'fresh',count:10,subjects:[...(props.freshSubjects||props.catalog.subjects)],topics:[],difficulty:'All',pool:'all',seed:Math.floor(Math.random()*4294967296),balance:false,minutes:15});
function start(){form.topics=form.topics.filter(t=>form.subjects.includes(t.split('\u001f')[0]));form.post('/attempts')}
</script><template><Head title="Practice"/><div class="page-title"><div><p class="eyebrow">Choose your round</p><h1>{{modes[form.mode]}}</h1></div><img class="portrait" :src="art[form.mode==='fresh'?'temaki':form.mode==='exam'?'wasabi':'maki']" alt="Practice sushi character"></div><form class="panel" @submit.prevent="start"><label>Study mode<select v-model="form.mode"><option value="fresh">Fresh Catch 10</option><option value="tutor">Maki Mentor</option><option value="exam">Wasabi Rush</option></select></label><Settings :form="form" :catalog="catalog"/><Errors :errors="form.errors"/><button class="primary" :disabled="form.processing">{{form.processing?'Preparing…':'Start round'}}</button></form></template>
